import{_ as l,o as t,c as e,aw as a}from"./chunks/framework.DLufY-ao.js";const m=JSON.parse('{"title":"TDD","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/testing/testing/concepts/tdd.md","filePath":"wiki/dev-commit/testing/testing/concepts/tdd.md"}'),o={name:"wiki/dev-commit/testing/testing/concepts/tdd.md"};function n(r,i,s,d,c,D){return t(),e("div",null,[...i[0]||(i[0]=[a('<h1 id="tdd" tabindex="-1">TDD <a class="header-anchor" href="#tdd" aria-label="Permalink to &quot;TDD&quot;">​</a></h1><ul><li><strong>Test-Diven Development, TDD (Разработка через тестирование)</strong> техника разработки программного обеспечения, которая основывается на повторении очень коротких циклов разработки: сначала пишется тест, покрывающий желаемое изменение, затем пишется код, который позволит пройти тест, и под конец проводится рефакторинг нового кода к соответствующим стандартам</li><li>Разработка через тестирование требует от разработчика создания автоматизированных модульных тестов, определяющих требования к коду непосредственно перед написанием самого кода. Тест содержит проверки условий, которые могут либо выполняться, либо нет. Когда они выполняются, говорят, что тест пройден. Прохождение теста подтверждает поведение, предполагаемое программистом</li><li>Разработка через тестирование тесно связана с такими принципами KISS и YAGNI</li><li><strong>Acceptance Test-driven Development, ATDD (разработка через приёмочное тестирование)</strong> критерии, описанные заказчиком, автоматизируются в приёмочные тесты, используемые потом в обычном процессе разработки через модульное тестирование (unit test-driven development, UTDD). При разработке через приёмочное тестирование, команда разработчиков сконцентрирована на чёткой задаче: удовлетворить приёмочные тесты, которые отражают соответствующие требования пользователя</li><li>TDD - это больше о программировании и тестировании на уровне технической реализации продукта, когда тесты создают сами разработчики</li><li>TDD - в голове придумываешь фичу и сразу на неё тесты. Потом фичу реализуешь, чтобы тесты не падали, любым способом. Как только тесты работают - делаешь рефакторинг написанного</li></ul><h2 id="алгоритм" tabindex="-1">Алгоритм <a class="header-anchor" href="#алгоритм" aria-label="Permalink to &quot;Алгоритм&quot;">​</a></h2><ul><li><ol><li>Придумана фича</li></ol></li><li><ol start="2"><li>На нее написаны тесты</li></ol></li><li><ol start="3"><li>Реализация фичи, чтобы не падали тесты</li></ol></li><li><ol start="4"><li>После рабочих тестов делается рефакторинг написанного</li></ol></li></ul><h2 id="недостатки" tabindex="-1">Недостатки <a class="header-anchor" href="#недостатки" aria-label="Permalink to &quot;Недостатки&quot;">​</a></h2><ul><li>Требуется больше времени на разработку и поддержку</li><li>Существуют задачи, которые невозможно (по крайней мере, на текущий момент) решить только при помощи тестов. В частности, TDD не позволяет механически продемонстрировать адекватность разработанного кода в области безопасности данных и взаимодействия между процессами</li><li>Разработку через тестирование сложно применять в тех случаях, когда для тестирования необходимо прохождение функциональных тестов. Примерами может быть: разработка интерфейсов пользователя, программ, работающих с базами данных, а также того, что зависит от специфической конфигурации сети</li></ul><h2 id="цикл-разработки-через-тестирование" tabindex="-1">Цикл разработки через тестирование <a class="header-anchor" href="#цикл-разработки-через-тестирование" aria-label="Permalink to &quot;Цикл разработки через тестирование&quot;">​</a></h2><ol><li>Добавление теста При разработке через тестирование, добавление каждой новой функциональности (англ. feature) в программу начинается с написания теста. Неизбежно этот тест не будет проходить, поскольку соответствующий код ещё не написан. Чтобы написать тест, разработчик должен чётко понимать предъявляемые к новой возможности требования. Для этого рассматриваются возможные сценарии использования и пользовательские истории. Новые требования могут также повлечь изменение существующих тестов</li><li>Запуск всех тестов: убедиться, что новые тесты не проходят</li><li>Написать код На этом этапе пишется новый код так, что тест будет проходить</li><li>Запуск всех тестов: убедиться, что все тесты проходят</li><li>Рефакторинг</li><li>Повторить цикл Шаги следует делать небольшими, от 1 до 10 изменений между запусками тестов</li></ol>',8)])])}const u=l(o,[["render",n]]);export{m as __pageData,u as default};
